const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),vm=require('node:vm'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'..'),dir=path.join(root,'docs/course-expansion-20261017');
const {course:c,photo:p}=JSON.parse(fs.readFileSync(path.join(dir,'official-route-manifest.json'))),proof=JSON.parse(fs.readFileSync(path.join(dir,'official-route-proof.json'))),evidence=JSON.parse(fs.readFileSync(path.join(dir,'official-route-pet-evidence.json')));
const coords=[...proof.originalGPX.matchAll(/<trkpt\s+lat="([^"]+)"\s+lon="([^"]+)"/g)].map(m=>[+m[1],+m[2]]);
assert.deepEqual(c.path,coords);assert.equal(coords.length,140);assert.equal(crypto.createHash('sha256').update(proof.originalGPX).digest('hex'),proof.gpxSha256);assert.equal(proof.source,c.source);assert.equal(c.diff,'미확인');assert.equal(evidence.pet.acmpyTypeCd,'전구역 동반가능');assert.equal(evidence.place.contentId,'2043017');assert(evidence.pet.acmpyPsblCpam.includes('전 견종'));
function meters(a,b){const r=Math.PI/180,h=Math.sin((b[0]-a[0])*r/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin((b[1]-a[1])*r/2)**2;return 12742000*Math.asin(Math.min(1,Math.sqrt(h)))}
let length=0;for(let i=1;i<coords.length;i++){const d=meters(coords[i-1],coords[i]);assert(d<110);length+=d}assert(Math.abs(length-proof.meters)<.01);assert.equal(c.distance,'약 '+(length/1000).toFixed(2)+'km');
for(const b of JSON.parse(fs.readFileSync(path.join(dir,'baseline.json')))){let n=0;for(const p of coords)if((b.path?.length?b.path:[[b.lat,b.lng]]).some(q=>meters(p,q)<30))n++;assert(n/coords.length<.2,'Overlaps '+b.name)}
const info=require('../course-info.js'),pet=require('../course-pet-access.js'),photos=require('../course-photos.js');const ctx={CourseInfo:info};vm.createContext(ctx);for(const f of ['course-routes.js','course-expansion-300.js','course-expansion-20261009.js','course-expansion-20261009-night.js','course-expansion-20261017.js'])vm.runInContext(fs.readFileSync(path.join(root,f),'utf8'),ctx);
assert(pet.get(c));assert.equal(ctx.CourseRoutes.get(c).proposed,false);assert.equal(ctx.CourseRoutes.get(c).geometryProvider,'두루누비 공식 GPX');assert(ctx.CourseRoutes.isLoop(ctx.CourseRoutes.get(c)));
const edited={...c,path:c.path.map(p=>[...p])};edited.path[1][0]+=.0001;assert.equal(pet.get(edited),null);assert.equal(ctx.CourseRoutes.get(edited),null);assert.equal(pet.get({...c,name:'changed'}),null);
assert(photos.get(c));assert(p.noCrop);assert(p.width>0&&p.height>0);assert.equal(crypto.createHash('sha256').update(fs.readFileSync(path.join(root,p.src))).digest('hex'),p.sourceSha256);console.log('PASS: official GPX 140/140 original points, no baseline overlap, explicit full-route pet scope, photo hash and edited-route rejection.');
